29: /// A state machine that wraps lines on word boundaries.
30: #[derive(Debug, Default, Clone)]
31: pub struct WordWrapper<'a, O, I>
32: where
33:     // Outer iterator providing the individual lines
34:     O: Iterator<Item = (I, Alignment)>,
35:     // Inner iterator providing the styled symbols of a line Each line consists of an alignment and
36:     // a series of symbols
37:     I: Iterator<Item = StyledGrapheme<'a>>,
38: {
39:     /// The given, unprocessed lines
40:     input_lines: O,
41:     max_line_width: u16,
42:     wrapped_lines: VecDeque<Vec<StyledGrapheme<'a>>>,
43:     current_alignment: Alignment,
44:     current_line: Vec<StyledGrapheme<'a>>,
45:     /// Removes the leading whitespace from lines
46:     trim: bool,
47: 
48:     // These are cached allocations that hold no state across next_line invocations
49:     pending_word: Vec<StyledGrapheme<'a>>,
50:     pending_whitespace: VecDeque<StyledGrapheme<'a>>,
51:     pending_line_pool: Vec<Vec<StyledGrapheme<'a>>>,
52: }
53: 
54: impl<'a, O, I> WordWrapper<'a, O, I>
55: where
56:     O: Iterator<Item = (I, Alignment)>,
57:     I: Iterator<Item = StyledGrapheme<'a>>,
58: {
59:     /// Create a new `WordWrapper` with the given lines and maximum line width.
60:     pub const fn new(lines: O, max_line_width: u16, trim: bool) -> Self {
61:         Self {
62:             input_lines: lines,
63:             max_line_width,
64:             wrapped_lines: VecDeque::new(),
65:             current_alignment: Alignment::Left,
66:             current_line: vec![],
67:             trim,
68: 
69:             pending_word: Vec::new(),
70:             pending_line_pool: Vec::new(),
71:             pending_whitespace: VecDeque::new(),
72:         }
73:     }
74: 
75:     /// Split an input line (`line_symbols`) into wrapped lines
76:     /// and cache them to be emitted later
77:     fn process_input(&mut self, line_symbols: impl IntoIterator<Item = StyledGrapheme<'a>>) {
78:         let mut pending_line = self.pending_line_pool.pop().unwrap_or_default();
79:         let mut line_width = 0;
80:         let mut word_width = 0;
81:         let mut whitespace_width = 0;
82:         let mut non_whitespace_previous = false;
83: 
84:         self.pending_word.clear();
85:         self.pending_whitespace.clear();
86:         pending_line.clear();
87: 
88:         for grapheme in line_symbols {
89:             let is_whitespace = grapheme.is_whitespace();
90:             let symbol_width = grapheme.symbol.width() as u16;
91: 
92:             // ignore symbols wider than line limit
93:             if symbol_width > self.max_line_width {
94:                 continue;
95:             }
96: 
97:             let word_found = non_whitespace_previous && is_whitespace;
98:             // current word would overflow after removing whitespace
99:             let trimmed_overflow = pending_line.is_empty()
100:                 && self.trim
101:                 && word_width + symbol_width > self.max_line_width;
102:             // separated whitespace would overflow on its own
103:             let whitespace_overflow = pending_line.is_empty()
104:                 && self.trim
105:                 && whitespace_width + symbol_width > self.max_line_width;
106:             // current full word (including whitespace) would overflow
107:             let untrimmed_overflow = pending_line.is_empty()
108:                 && !self.trim
109:                 && word_width + whitespace_width + symbol_width > self.max_line_width;
110: 
111:             // append finished segment to current line
112:             if word_found || trimmed_overflow || whitespace_overflow || untrimmed_overflow {
113:                 if !pending_line.is_empty() || !self.trim {
114:                     pending_line.extend(self.pending_whitespace.drain(..));
115:                     line_width += whitespace_width;
116:                 }
117: 
118:                 pending_line.append(&mut self.pending_word);
119:                 line_width += word_width;
120: 
121:                 self.pending_whitespace.clear();
122:                 whitespace_width = 0;
123:                 word_width = 0;
124:             }
125: 
126:             // pending line fills up limit
127:             let line_full = line_width >= self.max_line_width;
128:             // pending word would overflow line limit
129:             let pending_word_overflow = symbol_width > 0
130:                 && line_width + whitespace_width + word_width >= self.max_line_width;
131: 
132:             // add finished wrapped line to remaining lines
133:             if line_full || pending_word_overflow {
134:                 let mut remaining_width = u16::saturating_sub(self.max_line_width, line_width);
135: 
136:                 self.wrapped_lines.push_back(mem::take(&mut pending_line));
137:                 line_width = 0;
138: 
139:                 // remove whitespace up to the end of line
140:                 while let Some(grapheme) = self.pending_whitespace.front() {
141:                     let width = grapheme.symbol.width() as u16;
142: 
143:                     if width > remaining_width {
144:                         break;
145:                     }
146: 
147:                     whitespace_width -= width;
148:                     remaining_width -= width;
149:                     self.pending_whitespace.pop_front();
150:                 }
151: 
152:                 // don't count first whitespace toward next word
153:                 if is_whitespace && self.pending_whitespace.is_empty() {
154:                     continue;
155:                 }
156:             }
157: 
158:             // append symbol to a pending buffer
159:             if is_whitespace {
160:                 whitespace_width += symbol_width;
161:                 self.pending_whitespace.push_back(grapheme);
162:             } else {
163:                 word_width += symbol_width;
164:                 self.pending_word.push(grapheme);
165:             }
166: 
167:             non_whitespace_previous = !is_whitespace;
168:         }
169: 
170:         // append remaining text parts
171:         if pending_line.is_empty()
172:             && self.pending_word.is_empty()
173:             && !self.pending_whitespace.is_empty()
174:             && self.trim
175:         {
176:             self.wrapped_lines.push_back(vec![]);
177:         }
178:         if !pending_line.is_empty() || !self.trim {
179:             pending_line.extend(self.pending_whitespace.drain(..));
180:         }
181:         pending_line.append(&mut self.pending_word);
182: 
183:         #[expect(clippy::else_if_without_else)]
184:         if !pending_line.is_empty() {
185:             self.wrapped_lines.push_back(pending_line);
186:         } else if pending_line.capacity() > 0 {
187:             self.pending_line_pool.push(pending_line);
188:         }
189:         if self.wrapped_lines.is_empty() {
190:             self.wrapped_lines.push_back(vec![]);
191:         }
192:     }
